SELECT

        FROM blog_message m JOIN sys_user u ON u.user_id=m.user_id WHERE m.message_id=#{id}
        AND m.user_id=#{user}

SELECT , , ru.nickname AS reply_to_nickname, LEFT(p.content, 120) AS reply_to_content, EXISTS (SELECT 1 FROM blog_message r WHERE r.parent_id = m.message_id) AS has_children FROM blog_message m JOIN sys_user u ON u.user_id = m.user_id LEFT JOIN blog_message p ON p.message_id = m.parent_id LEFT JOIN sys_user ru ON ru.user_id = p.user_id
AND m.parent_id IS NULL AND m.parent_id = #{parent}
ORDER BY m.create_time DESC, m.message_id DESC

